FILE: app/src/fly-controls.ts
```ts
import { attachConfigurableFreeControl } from "@babylonjs/lite";
import type { FreeCamera, SceneContext } from "@babylonjs/lite";

export function attachFlyControls(
  camera: FreeCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext
): () => void {
  return attachConfigurableFreeControl(camera, canvas, scene, {
    upKeys: ["Space"],
    downKeys: ["PageDown"],
    fastKeys: ["ShiftLeft", "ShiftRight"],
    fastMultiplier: 3,
  });
}
```

I used the library’s configurable free-camera control so Shift is only a 3× speed key while Space and PageDown handle vertical movement, and I returned the library’s dispose function so no listeners or frame steps remain. I was not sure whether PageUp should also rise, so I treated the stated key list as exclusive; add `"PageUp"` to `upKeys` if you want to keep the default behavior.
